<?php
/**
 * Antalya POS Staff Member Delete Handler
 *
 * @package Antalya_POS
 * @since 6.4
 */

if (!defined('ABSPATH')) {
    exit;
}

if (isset($_GET['del_staff'])) {
    if (!current_user_can('manage_options')) {
        wp_die(esc_html__('You do not have sufficient permissions to perform this action.', 'antalya-pos'));
    }

    $staff_id = intval($_GET['del_staff']);
    if ($staff_id > 0) {
        // Verify CSRF nonce generated by wp_nonce_url() in staff-list.php & staff-view.php
        check_admin_referer('rtpos_delete_staff_' . $staff_id);

        global $wpdb;
        $t_staff   = $wpdb->prefix . 'rtpos_staff';
        $svg_check = '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"><polyline points="20 6 9 17 4 12"/></svg>';

        $deleted = $wpdb->delete(
            $t_staff,
            ['id' => $staff_id],
            ['%d']
        );

        if ($deleted !== false) {
            echo '<div class="apos-alert stf-alert-flex">' . $svg_check . '<span>' . sprintf(
                /* translators: %d: staff ID */
                esc_html__('Staff member #%d removed successfully!', 'antalya-pos'),
                $staff_id
            ) . '</span></div>';
        }
    }
}